import { TOOL_FULL } from "../domain/tool.ts";
import type { PolicyInput, Stored } from "../domain/verdict.ts";
import {
  DENY_ASK,
  DENY_FORBIDDEN,
  NOTE_LOGIN,
  NOTE_UNREAD,
  RESULT_CONDITIONS,
  RESULT_RECORDED,
} from "../prompts.ts";
import type { Gathered } from "./gather.ts";

/** The record of the answer `input` for the check `g`. */
export const recordOf = (
  input: PolicyInput,
  g: Gathered,
  key: string,
  time: number,
): Stored => ({
  repo: key,
  hash: g.hash,
  verdict: input.verdict,
  quote: input.verdict === "silent" ? "" : input.quote,
  conditions: input.conditions,
  time,
});

/** The result that the tool gives to Claude for `record`. */
export const replyOf = (record: Stored): string =>
  record.verdict === "forbidden"
    ? DENY_FORBIDDEN({ repo: record.repo, quote: record.quote })
    : record.verdict === "conditions"
      ? RESULT_CONDITIONS({ repo: record.repo, conditions: record.conditions })
      : RESULT_RECORDED({ repo: record.repo, verdict: record.verdict });

/** The text that asks Claude to read the files of `g` and record a verdict. */
export const askText = (g: Gathered, hasLogin: boolean): string =>
  DENY_ASK({
    repo: g.target.key,
    files: g.files.map((f) => `- ${f.shown}`).join("\n"),
    notes: [
      ...(hasLogin ? [] : [NOTE_LOGIN]),
      ...g.notes.map((what) => NOTE_UNREAD({ what })),
    ].join("\n"),
    tool: TOOL_FULL,
  });
